<script setup lang="ts">
import { router } from '@inertiajs/vue3'; import { FileText, Plus, Search } from 'lucide-vue-next'; import { computed, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import Button from '@/Core/Components/Button.vue'; import Card from '@/Core/Components/Card.vue'; import DataTable, { type Column } from '@/Core/Components/DataTable.vue'; import EmptyState from '@/Core/Components/EmptyState.vue'; import Input from '@/Core/Components/Input.vue'; import PageHeader from '@/Core/Components/PageHeader.vue'; import Pagination from '@/Core/Components/Pagination.vue'; import Select from '@/Core/Components/Select.vue'; import { useFormat } from '@/Core/composables/useFormat'; import TenantLayout from '@/Core/Layouts/TenantLayout.vue'; import { route } from '@/Core/lib/route'; import type { Paginated } from '@/Core/types'; import CrmStatusBadge from '../../../Components/CrmStatusBadge.vue'; import QuoteFormDialog from '../../../Components/QuoteFormDialog.vue'; import SalesNav from '../../../Components/SalesNav.vue'; import type { QuoteFormOptions, QuoteKind, QuoteStatus, QuoteSummary } from '../../../Components/types';
defineOptions({ layout: TenantLayout }); const props = defineProps<{ quotes: Paginated<QuoteSummary>; filters: { search: string; status: QuoteStatus | null; kind: QuoteKind | null }; statuses: QuoteStatus[]; kinds: QuoteKind[]; form: QuoteFormOptions; canCreate: boolean }>(); const { t } = useI18n(); const format = useFormat(); const formOpen = ref(false); const search = ref(props.filters.search); const status = ref(props.filters.status ?? ''); const kind = ref(props.filters.kind ?? ''); const loading = ref(false); const statusOptions = computed(() => [{ value: '', label: t('crm.common.all') }, ...props.statuses.map((value) => ({ value, label: t(`crm.status.${value}`) }))]); const kindOptions = computed(() => [{ value: '', label: t('crm.common.all') }, ...props.kinds.map((value) => ({ value, label: t(`crm.quoteKinds.${value}`) }))]); const columns = computed<Column[]>(() => [{ key: 'number', label: t('crm.fields.number') }, { key: 'title', label: t('crm.fields.title') }, { key: 'status', label: t('crm.fields.status') }, { key: 'customer', label: t('crm.sales.quotes.customer'), hideable: true }, { key: 'total', label: t('crm.sales.quotes.total'), align: 'right' }, { key: 'valid', label: t('crm.fields.validUntil'), hideable: true }, { key: 'actions', label: t('crm.common.actions'), srOnly: true, align: 'right' }]); function apply(): void { router.get(route('crm.sales.quotes.index'), { search: search.value || undefined, status: status.value || undefined, kind: kind.value || undefined }, { preserveState: true, replace: true, onStart: () => { loading.value = true; }, onFinish: () => { loading.value = false; } }); }
</script>
<template><PageHeader :eyebrow="t('crm.eyebrow')" :title="t('crm.sales.quotes.title')" :description="t('crm.sales.quotes.description')"><template v-if="canCreate" #actions><Button variant="primary" @click="formOpen = true"><template #icon><Plus class="size-4" aria-hidden="true" /></template>{{ t('crm.sales.quotes.add') }}</Button></template></PageHeader><SalesNav current="quotes" /><Card flush><DataTable :columns="columns" :rows="quotes.data" row-key="id" :caption="t('crm.sales.quotes.title')" :loading="loading" storage-key="crm-quotes"><template #toolbar><form class="flex min-w-0 flex-1 flex-wrap items-end gap-2" @submit.prevent="apply"><Input v-model="search" :label="t('crm.sales.quotes.search')" class="min-w-48 flex-1" type="search"><template #leading><Search class="size-4" aria-hidden="true" /></template></Input><Select v-model="status" :options="statusOptions" :label="t('crm.fields.status')" class="w-full sm:w-36" /><Select v-model="kind" :options="kindOptions" :label="t('crm.fields.type')" class="w-full sm:w-36" /><Button type="submit" size="sm">{{ t('crm.common.search') }}</Button></form></template><template #cell-number="{ row }"><span class="font-mono text-xs text-ink-muted">{{ row.number }}</span></template><template #cell-title="{ row }"><Button variant="ghost" size="sm" :href="route('crm.sales.quotes.show', { quote: row.id })" class="max-w-64 truncate">{{ row.title }}</Button></template><template #cell-status="{ row }"><CrmStatusBadge :status="row.status" /></template><template #cell-customer="{ row }"><span class="text-ink-muted">{{ row.company?.name ?? row.contact?.name ?? t('crm.common.notSet') }}</span></template><template #cell-total="{ row }"><span class="tabular font-mono">{{ format.money(row.totalAmount, row.currency) }}</span></template><template #cell-valid="{ row }"><span class="tabular text-ink-muted">{{ row.validUntil ? format.date(row.validUntil) : t('crm.common.notSet') }}</span></template><template #cell-actions="{ row }"><Button size="sm" variant="ghost" :href="route('crm.sales.quotes.show', { quote: row.id })">{{ t('crm.common.view') }}</Button></template><template #empty><EmptyState :title="t('crm.sales.quotes.empty')"><template #icon><FileText /></template></EmptyState></template></DataTable><Pagination :meta="quotes" /></Card><QuoteFormDialog v-if="canCreate" v-model:open="formOpen" :options="form" /></template>
